const RUN='mac-three-findings-paired-20261102';
const fsr=(file='metrics-summary.csv')=>`出典：${RUN} / ${file}（今回再実行した合成評価）`;
const met=(kw)=>select(T.metrics,kw);
const barHist=(sl,study,range,case1,case2,title)=>{
 const hist=(name)=>T.histograms.filter(r=>r.study===study&&r.range_bin===range&&r.case===name).sort((a,b)=>a.bin-b.bin).map(r=>100*r.fraction);
 chart(sl,{title,categories:['0〜0.5','0.5〜1','1〜1.5','1.5〜2','2超'],series:[{name:'正常',values:hist(case1),fill:C.blue},{name:'申告改変',values:hist(case2),fill:C.red}],max:70,ytitle:'標本の割合（%）'});
};
