define('focusMeaning2',()=>page('結果②から言えること','自由な電力変更を許すと、位置の違いをRSSIで相殺できる',[['合成実験で確認したこと',['共通標本で、位置改変の警報率を正常付近まで戻せた']],['数理的に分かること',['同じ申告と同じRSSIを作る、異なる位置・電力の世界が存在']],['成立条件と限界',['各送信を単独受信、電力は自由、独立な位置・電力証拠なし','実機の実現可能な出力幅や指向性・移動制約を評価した結果ではない']]],fsr('summary.json')));
define('focusConditions3',()=>{const sl=base('実験③：同一送信を5台で受ける条件','別送信を別ノードで受ける元条件へ、観測を追加',fsr('summary.json'));table(sl,[['項目','追加条件の合成モデル'],['観測','同じ3D軌跡、同一送信、既知の5台配置。全台が受信'],['電力','送信ごとに共通電力SD8dB、飛行差SD3dB'],['伝搬・雑音','係数2.2を既知、各リンク独立雑音SD2／6dB'],['校正と評価','20校正飛行、30評価飛行、各240送信、10 seed'],['有利な仮定','対応付け既知、正常申告は真位置、遮蔽・時計誤差なし']],{h:355,columns:[205,671]});note(sl,['評価は72000送信。連続イベントを72000回の独立試行とは扱わない'],570);return sl;});
define('focusDetector3',()=>{const sl=base('実験③：各ノードで必要な電力を照合','1つの送信なら、5台の観測を同じ共通電力で説明できるはず',fsr('summary.json'));table(sl,[['処理','実装した計算'],['申告位置から計算','各ノードまでの申告距離dᵢ(q)'],['観測と申告から逆算','uᵢ = RSSIᵢ + 22 log₁₀dᵢ(q)'],['共通電力を除く','各uᵢから、受信ノード集合の平均uを引く'],['不整合の大きさ','平均を除いた残差のRMSをスコアに'],['警報の境界','正常校正スコアの95%点。評価データと分離']],{h:355,columns:[265,611]});note(sl,['RMSは残差の二乗平均平方根。ペア別の閾値ではない','逆算値は「申告が正しい場合に必要な電力」。実出力の測定ではない'],550);return sl;});
define('focusResult3',()=>{const sl=base('実験③の結果：雑音で検知率が変化','同じ5台・同じ飛行・同じ改変。変更するのはリンク雑音',fsr());chart(sl,{title:'全72,000送信を受信・判定した合成結果',categories:['正常','水平位置+30m','水平位置+100m'],series:[2,6].map((noise_sd_db,i)=>({name:'雑音SD'+noise_sd_db+'dB',fill:i?C.red:C.blue,values:[0,30,100].map(d=>100*met({study:'common5',case:'position'+d,noise_sd_db}).conditional_alarm_rate)})),max:100});note(sl,['正常：4.985／4.875%。30m改変：19.522／6.324%','100m改変：73.678／18.729%（順にSD2／6dB）','同じ配置の雑音比較。台数だけの純粋な効果を示す比較ではない'],540);return sl;});
define('focusNoise3',()=>{const sl=base('実験③：電力が消えても雑音は残る','同じ送信の共通電力を除いても、受信機ごとの誤差は除けない');txt(sl,'RSSI_A − RSSI_B',65,175,835,45,30,C.blue,true);txt(sl,'= −22 log₁₀(d_A / d_B) + ε_A − ε_B',65,245,835,65,30,C.black);table(sl,[['独立な各リンクの雑音','2台の差に残る雑音SD'],['SD2dB','√(2²+2²) ≈ 2.83dB'],['SD6dB','√(6²+6²) ≈ 8.49dB']],{y:350,h:195,columns:[450,426]});note(sl,['この表は2台差分の説明。実装の5台RMSスコアそのもののSDではない','雑音で正常の揺らぎも大きくなり、同じ位置改変を分離しにくくなる'],580);return sl;});
define('focusCompare',()=>{const sl=base('3つの実験は、同じ保証を比較していない','元条件での失敗と、条件追加後の検査を分ける');table(sl,[['条件','①②：単独受信','③：同一送信の複数受信'],['1送信のRSSI','1値','5値'],['未知電力への対応','正常分布で校正／攻撃で補償','共通成分をスコアから除去'],['伝搬','遮蔽・量子化・受信感度あり','伝搬既知、独立ガウス雑音'],['校正の基準','合成の通常申告・電力分布','正常申告が真位置という有利な条件'],['結果の意味','条件付きの警報、識別不能の反例','追加条件下の不整合検知']],{h:375,columns:[190,330,356]});note(sl,['③の検知率を、元の非同時監視で達成した性能として使わない'],585);return sl;});
define('focusSummary',()=>{const sl=base('今回、結果として言えること','自由電力・単独RSSIの問題は、観測件数だけでは解決しない');table(sl,[['結果','今回の根拠'],['① 位置のみの改変は分離が弱い','30m改変14.12%、正常10.95%。同じ1,388件'],['② 電力も変えると相殺可能','共通12,294件\n位置のみ30.316%、電力連動2.424%'],['③ 同じ送信を5台で受信','5台・100m改変\nSD2dB：73.678%、SD6dB：18.729%']],{h:300,columns:[375,501]});note(sl,['全て合成モデルでの結果。実RFの検知距離や機体の真正性は示していない','警報なしを位置の正しさの証明としない。雑音・配置の限界が残る'],530);return sl;});
define('focusFuture',()=>page('次に必要な評価','実機の条件で、仮定がどこまで成立するかを確認',[['元条件に必要な実測',['実効電力の変化幅・持続性、遮蔽、受信選択']],['追加観測に必要な実測',['同じ送信の対応付け、複数受信の重なり、正常位置誤差']],['研究としての次の判断',['元の非同時条件を維持するか、独立な位置証拠を追加するか']]]));
define('focusSources',()=>{const sl=base('データと再現方法','新しいRF実測は行わず、既存生成器で説明用の追加比較を実行');table(sl,[['対象','実体'],['今回の追加コード','experiments/week26-rssi-privacy/explain_three_results.py'],['入力条件','synthetic3d_config.json、sensitivity_config.json\nevent_scenarios_config.json'],['出力','mac-three-findings-paired-20261102\nmetrics-summary.csv、histogram-summary.csv、summary.json'],['実行','python explain_three_results.py --out <新しい出力先>']],{h:330,columns:[180,696]});note(sl,['既存の警報数・検知率を再現し、共通標本での比較を追加','詳しいコマンド・seed・出典は同梱MD。原論文のアルゴリズムの追試ではない'],550);footer(sl,'関連：Hu & Leus, IEEE TSP 2017, DOI:10.1109/TSP.2017.2684741（共通電力と受信強度差）');return sl;});
const ORDER=['focusCover','focusScenario','focusRoadmap','focusModel','focusGeometry1','focusConditions1','focusResult1','focusOverlap1','focusMeaning1','focusAttack2','focusCohort2','focusResult2','focusIdentical2','focusMeaning2','setup','focusConditions3','focusDetector3','focusResult3','focusNoise3','geometryMath','focusCompare','focusSummary','focusFuture','focusSources'];
P=await PresentationFile.importPptx(await FileBlob.load(REF));template=P.slides.items[4];coverTemplate=P.slides.items[0];
const slides=[];for(const key of ORDER){const sl=BANK[key]();slides.push(sl);log.at(-1).key=key;}
P.slides.keep(slides.map(sl=>P.slides.items.findIndex(s=>s.id===sl.id)));slides.forEach((sl,i)=>sl.moveTo(i));
const dir=path.join(CACHE,'E');await fs.mkdir(dir,{recursive:true});
await fs.writeFile(path.join(dir,'slide-map.json'),JSON.stringify(log.map((r,i)=>({slide:i+1,key:r.key,title:r.title,source:r.source,charts:r.slide.charts.items.length,tables:r.slide.tables.items.length})),null,2));
for(const sl of slides)for(const ch of sl.charts.items)for(const se of ch.series.items){se.values=se.values.map(v=>v===null?v:Number(v.toFixed(6)));if(se.xValues?.length)se.xValues=se.xValues.map(v=>Number(v.toFixed(6)));}
await (await PresentationFile.exportPptx(P)).save(path.join(dir,'draft.pptx'));console.log('E exported',slides.length);
for(let i=0;i<slides.length;i++){const b=await P.export({slide:slides[i],format:'png',scale:1});await fs.writeFile(path.join(dir,`slide-${i+1}.png`),new Uint8Array(await b.arrayBuffer()));if((i+1)%6===0)console.log('rendered',i+1);}
